#!/usr/bin/env node

import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

import {
  contractPath,
  repository,
  validateCleanReproducibility,
  workflowPath,
} from "./clean-reproducibility-lib.mjs";

export function renderReproducibilityWorkflow(contract) {
  const output = [
    "# Generated by tools/render-reproducibility-workflow.mjs from migration/clean-reproducibility.json.",
    "# Do not edit this file directly.",
    `name: ${contract.workflow.name}`,
    "",
    "on:",
    "  pull_request:",
    "  push:",
    "    branches:",
    ...contract.workflow.triggers.pushBranches.map((branch) => `      - ${branch}`),
    "",
    "permissions:",
    `  contents: ${contract.workflow.permissions.contents}`,
    "",
    "concurrency:",
    `  group: ${contract.workflow.concurrency.group}`,
    `  cancel-in-progress: ${contract.workflow.concurrency.cancelInProgress}`,
    "",
    "env:",
    `  CI_RUNTIME_IMAGE_DIGEST: ${contract.runtime.ciImageDigest}`,
    ...Object.entries(contract.runtime.environment).map(
      ([key, value]) => `  ${key}: ${JSON.stringify(value)}`
    ),
    "",
    "jobs:",
    "  reproducibility:",
    "    name: Two clean archive workspaces",
    `    runs-on: ${contract.workflow.runner}`,
    "    container:",
    `      image: ${contract.runtime.ciImage}`,
    `    timeout-minutes: ${contract.workflow.timeoutMinutes}`,
    "    steps:",
    "      - name: Check out exact revision",
    `        uses: actions/checkout@${contract.actions.checkout.sha} # ${contract.actions.checkout.version}`,
    "        with:",
    "          fetch-depth: 0",
    "      - name: Trust checked-out worktree",
    '        run: git config --global --add safe.directory "$GITHUB_WORKSPACE"',
    "      - name: Install pinned Node",
    `        uses: actions/setup-node@${contract.actions.setupNode.sha} # ${contract.actions.setupNode.version}`,
    "        with:",
    `          node-version: ${contract.runtime.node}`,
    "          check-latest: false",
    "      - name: Install pinned npm",
    `        run: ${contract.runtime.npmInstallCommand.join(" ")}`,
    "      - name: Bootstrap pinned registry tarballs",
    `        run: ${contract.runtime.npmRegistryBootstrapCommand.join(" ")}`,
    "      - name: Verify C02 contract and generated workflow",
    "        run: node tools/verify-clean-reproducibility.mjs",
    "      - name: Run two clean archive workspaces",
    `        run: node tools/prove-clean-reproducibility.mjs --output ${contract.proof.output}`,
    "      - name: Verify reproducibility proof",
    `        run: node tools/verify-clean-reproducibility.mjs --proof ${contract.proof.output}`,
    "      - name: Upload reproducibility proof",
    "        if: always()",
    `        uses: actions/upload-artifact@${contract.actions.uploadArtifact.sha} # ${contract.actions.uploadArtifact.version}`,
    "        with:",
    `          name: ${contract.workflow.proofArtifactName}`,
    "          path: .ci-results/reproducibility/**",
    "          if-no-files-found: ignore",
    "          include-hidden-files: true",
    `          retention-days: ${contract.workflow.artifactRetentionDays}`,
    "      - name: Upload compact reproducibility failure evidence",
    "        if: failure()",
    `        uses: actions/upload-artifact@${contract.actions.uploadArtifact.sha} # ${contract.actions.uploadArtifact.version}`,
    "        with:",
    "          name: clean-reproducibility-failure-${{ github.run_id }}-${{ github.run_attempt }}",
    "          path: |",
    "            .ci-results/reproducibility/**",
    "          if-no-files-found: ignore",
    "          include-hidden-files: true",
    `          retention-days: ${contract.workflow.artifactRetentionDays}`,
  ];
  return `${output.join("\n")}\n`;
}

function argument(name) {
  const index = process.argv.indexOf(name);
  return index === -1 ? null : process.argv[index + 1];
}
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const unexpected = process.argv.slice(2).filter((argumentValue, index, all) => {
    if (argumentValue === "--write") return false;
    if (argumentValue === "--contract" && all[index + 1]) return false;
    if (index > 0 && all[index - 1] === "--contract") return false;
    return true;
  });
  if (unexpected.length)
    throw new Error(`unknown arguments: ${unexpected.join(" ")}`);
  const source = argument("--contract") ?? path.join(repository, contractPath);
  const contract = JSON.parse(readFileSync(source, "utf8"));
  const rendered = renderReproducibilityWorkflow(contract);
  const target = path.join(repository, workflowPath);
  if (process.argv.includes("--write")) writeFileSync(target, rendered);
  else if (readFileSync(target, "utf8") !== rendered)
    throw new Error(
      "CLEAN_REPRODUCIBILITY_WORKFLOW_RENDER_FAILED: workflow differs; run render-reproducibility-workflow.mjs --write"
    );
  await validateCleanReproducibility({ contract: source });
  console.log(`CLEAN_REPRODUCIBILITY_WORKFLOW_OK path=${workflowPath}`);
}
